#!/bin/bash
# Make a patch folder with some SWAN changes left out, for tests that compare a
# build with and without one change.
#
#   tests/tools/variant_patches.sh SOURCE OUTDIR NAME[,NAME...]
#
# SOURCE  a COAWST tree or tarball at the pinned commit (its SWAN/src is read)
# OUTDIR  created: a copy of build/coawst/patches whose SWAN patches are
#         regenerated by generators/make_swan_patches.py --without NAME,...
# A SWAN patch that builds on a left-out change cannot be generated; it is
# removed from OUTDIR and listed (a series that needs it fails to build).
# Use with build/coawst/build.sh --patch-dir OUTDIR --series FILE.
set -euo pipefail
src=$1 out=$(realpath -m "$2") without=$3
pdir=$(cd "$(dirname "$0")/../../build/coawst/patches" && pwd)
rm -rf "$out" && cp -r "$pdir" "$out"
tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT
if [ -d "$src" ]; then
    cp -r "$src/SWAN/src" "$tmp/src"
else
    top=$( { tar -tzf "$src" 2>/dev/null || true; } | sed -n "1s#/.*##p")
    tar -xzf "$src" -C "$tmp" "$top/SWAN/src"
    mv "$tmp/$top/SWAN/src" "$tmp/src"
fi
swan=$(grep -oE '"[0-9]-[a-z]+/swan-[a-z0-9-]+\.patch"' "$pdir/generators/make_swan_patches.py" | tr -d '"')
for p in $swan; do rm -f "$out/$p"; done
python3 -I "$pdir/generators/make_swan_patches.py" "$tmp/src" "$out" --without "$without" \
    > "$tmp/gen.log" 2>&1 || true
sed 's/^/   /' "$tmp/gen.log"
missing=""
for p in $swan; do [ -f "$out/$p" ] || missing="$missing $p"; done
echo "variant without $without in $out${missing:+; not generated (they build on a left-out change):$missing}"
